<?php
session_start();require '../config/database.php'; require '../lib_security.php';if(!isset($_SESSION['user'])||$_SESSION['user']['role']!=='admin'){header('Location: ../login.php');exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['mark_paid'])){ verifyCsrf(); $id=(int)$_POST['mark_paid']; $q=$pdo->prepare('UPDATE fee_challans SET status="paid",paid_at=NOW() WHERE id=? AND status<>"paid"'); $q->execute([$id]); header('Location: fees.php'); exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && !isset($_POST['mark_paid'])){ verifyCsrf();$sid=(int)$_POST['student_id'];$purpose=trim($_POST['purpose']);$amount=(float)$_POST['amount'];$due=$_POST['due_date'];$no='CH-'.date('YmdHis').'-'.random_int(10,99);try{$q=$pdo->prepare('INSERT INTO fee_challans(student_id,challan_no,purpose,amount,issue_date,due_date) VALUES(?,?,?,?,CURDATE(),?)');$q->execute([$sid,$no,$purpose,$amount,$due]);}catch(Throwable $e){$error='Could not create challan.';}header('Location: fees.php');exit;}
$students=$pdo->query('SELECT s.id,s.roll_no,u.name FROM students s JOIN users u ON u.id=s.user_id ORDER BY u.name')->fetchAll();$fees=$pdo->query('SELECT f.*,s.roll_no,u.name FROM fee_challans f JOIN students s ON s.id=f.student_id JOIN users u ON u.id=s.user_id ORDER BY f.issue_date DESC,f.id DESC')->fetchAll();$pageTitle='Fee Management';require '../includes/header.php';?><div class="container py-4"><div class="d-flex justify-content-between"><h2>Fee Management</h2><a href="../admin.php" class="btn btn-outline-secondary">Dashboard</a></div><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><div class="card shadow-sm my-3"><div class="card-body"><h5>Create Challan</h5><form method="post" class="row g-2"><?php echo csrfField(); ?><div class="col-md-4"><select name="student_id" class="form-select" required><option value="">Student</option><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=htmlspecialchars($s['roll_no'].' — '.$s['name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><input name="purpose" class="form-control" placeholder="Tuition / Admission / Exam" required></div><div class="col-md-2"><input name="amount" type="number" step="0.01" min="0" class="form-control" placeholder="Amount" required></div><div class="col-md-2"><input name="due_date" type="date" class="form-control" required></div><div class="col-md-1"><button class="btn btn-primary">Create</button></div></form></div></div><div class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Student</th><th>Challan</th><th>Purpose</th><th>Amount</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($fees as $f):?><tr><td><?=htmlspecialchars($f['roll_no'].' — '.$f['name'])?></td><td><?=htmlspecialchars($f['challan_no'])?></td><td><?=htmlspecialchars($f['purpose'])?></td><td>Rs. <?=number_format($f['amount'],2)?></td><td><?=htmlspecialchars($f['due_date'])?></td><td><?=htmlspecialchars($f['status'])?></td><td><a class="btn btn-sm btn-outline-primary" href="../fee_receipt.php?id=<?=$f['id']?>">Print</a><?php if($f['status']!=='paid'):?> <form method="post" class="d-inline"><?php echo csrfField(); ?><button name="mark_paid" value="<?=$f['id']?>" class="btn btn-sm btn-outline-success">Mark Paid</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require '../includes/footer.php';?>
